from collections import deque

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                set_i = set(properties[i])
                set_j = set(properties[j])
                common = len(set_i & set_j)
                if common >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        visited = [False] * n
        count = 0

        for i in range(n):
            if not visited[i]:
                count += 1
                queue = deque([i])
                visited[i] = True
                while queue:
                    node = queue.popleft()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        return count
from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Precompute the sets for each property list
        sets = [set(arr) for arr in properties]
        # Initialize adjacency list
        adj = [[] for _ in range(n)]

        # Build the adjacency list based on the intersection condition
        for i in range(n):
            for j in range(i + 1, n):
                common = len(sets[i] & sets[j])
                if common >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Find the number of connected components using DFS
        visited = [False] * n
        count = 0

        for i in range(n):
            if not visited[i]:
                count += 1
                # Use stack for DFS
                stack = [i]
                visited[i] = True
                while stack:
                    current = stack.pop()
                    for neighbor in adj[current]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)

        return count
